import fs from "fs";
import path from "path";
import crypto from "crypto";
import zlib from "zlib";

const targetFile = path.resolve(process.cwd(), "src", "features", "music", "MusicMiniPlayer.tsx");
const expectedPreviousSha = "19cbe6daba3c920a61c7cb42aaaa687be1dcd6b0d05b22d5d19fc293488af09e";
const replacementSha = "37865f201f1dfc3a59df1840b0ad93b35eb34a4dbe94e56d8f2c28a4a1338139";
const payload = "";

if (!fs.existsSync(targetFile)) {
  console.error(`ERROR: Target file not found: ${targetFile}`);
  console.error("Run this from the MVPTrainerPro-Personal repository root.");
  process.exit(1);
}

const current = fs.readFileSync(targetFile);
const currentSha = crypto.createHash("sha256").update(current).digest("hex");
if (currentSha === replacementSha) {
  console.log("MVP Trainer V5 R8.5 is already installed. No changes needed.");
  process.exit(0);
}
if (currentSha !== expectedPreviousSha) {
  console.warn("WARNING: Current MusicMiniPlayer.tsx differs from the expected R8.4.1 baseline.");
  console.warn("A timestamped backup will be created before applying the complete R8.5 replacement.");
}

const replacement = zlib.inflateSync(Buffer.from(payload, "base64"));
const verifiedSha = crypto.createHash("sha256").update(replacement).digest("hex");
if (verifiedSha !== replacementSha) {
  console.error("ERROR: Embedded R8.5 payload failed SHA verification.");
  process.exit(1);
}

const stamp = new Date().toISOString().replace(/[:.]/g, "-");
const backupPath = `${targetFile}.bak-r8-5-${stamp}`;
fs.copyFileSync(targetFile, backupPath);
fs.writeFileSync(targetFile, replacement);

console.log("MVP Trainer V5 R8.5 applied successfully.");
console.log(`Updated: ${path.relative(process.cwd(), targetFile)}`);
console.log(`Backup:  ${path.relative(process.cwd(), backupPath)}`);
console.log(`SHA-256: ${replacementSha}`);
console.log("");
console.log("Next: run npm run build, then test desktop + mobile before committing.");
